<div class="top"><h1>Clients</h1></div><form class="filters-bar" method="get"><input name="q" placeholder="Nom, e-mail, téléphone" value="<?= e(get('q')) ?>"><button class="btn btn-p btn-sm">Rechercher</button></form>
<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Client</th><th>Contact</th><th>Commandes</th><th class="right">Payé</th><th>Inscrit</th></tr></thead><tbody><?php foreach ($rows as $u): ?><tr><td><a href="/admin/clients/<?= (int) $u['id'] ?>"><b><?= e($u['name'] ?: '—') ?></b></a><?= $u['active'] ? '' : ' <span class="badge b-bad">désactivé</span>' ?></td><td><?= e($u['email']) ?><br><small class="muted"><?= e($u['phone']) ?></small></td><td><?= (int) $u['n_orders'] ?></td><td class="right"><?= money($u['spent']) ?></td><td><?= fdate($u['created_at']) ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="center muted">Aucun client.</td></tr><?php endif; ?></tbody></table></div>
